const fmt=new Intl.NumberFormat('fr-FR',{maximumFractionDigits:1}),exact=new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2});
const money=v=>v>=1e6?fmt.format(v/1e6)+' M€':v>=1000?fmt.format(v/1000)+' k€':fmt.format(v)+' €';
const labels={included:'BILAN ESTIMÉ',modeled:'HYPOTHÈSE',overlap:'NON ADDITIONNÉ',pending:'À VENTILER',excluded:'HORS COMPTEUR',volume:'REPÈRE',announced:'ANNONCE',historical:'HISTORIQUE'};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let frame,selected='central',activeFilter='included';
function modelTable(r){if(!r.included)return '';const ks=['low','central','high'];let html='<div class="table-scroll"><table class="model-table"><thead><tr><th>Calcul / paramètre</th><th>Bas</th><th>Central</th><th>Haut</th></tr></thead><tbody>';if(r.terms)r.terms.forEach(t=>{html+=`<tr class="term-head"><th colspan="4">${escape(t.label)} · produit des paramètres ci-dessous</th></tr>`;t.factors.forEach(f=>html+=`<tr><td>${escape(f.name)}<small>${escape(f.kind)}</small></td>${f.values.map(v=>`<td>${exact.format(v)}</td>`).join('')}</tr>`);html+=`<tr><th>Sous-total (€)</th>${ks.map((k,i)=>`<td>${exact.format(t.factors.reduce((acc,f)=>acc*f.values[i],1))}</td>`).join('')}</tr>`});html+=`<tr class="model-total"><th>${r.terms?'Somme de la ligne':'Montant retenu'} (€)</th>${ks.map(k=>`<td>${exact.format(r['amount_'+k])}</td>`).join('')}</tr></tbody></table></div>`;if(r.terms)html+='<p class="source-date">Les décimales rendent le calcul reproductible, pas plus certain. Les parts 0,5 et 0,75 signifient 50 % et 75 %. Chaque sous-total est un produit ; la ligne additionne ses sous-totaux.</p>';return html}
function render(filter){activeFilter=filter;const rs=data.rows.filter(r=>filter==='all'||(filter==='included'&&r.included)||(filter==='references'&&!r.included)||(r.included&&r.category===filter)||r.status===filter);document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter))});document.querySelector('#filter-count').textContent=rs.length+' fiches · montants du scénario '+data.scenario_labels[selected].toLowerCase()+' · ouvrez une ligne pour voir le calcul';document.querySelector('#expenses').innerHTML=rs.map(r=>{const s=r.source?data.sources[r.source]:null;return `<details class="expense"><summary><span class="num">${String(data.rows.indexOf(r)+1).padStart(2,'0')}</span><h3>${escape(r.name)}</h3><span class="tag ${r.included?'estimate':''}">${labels[r.status]}</span><span class="value">${escape(r.included?money(r['amount_'+selected]):r.value)}</span><span class="plus" aria-hidden="true">+</span></summary><div class="expense-content">${r.included?`<p class="confidence"><b>Confiance : ${escape(r.confidence)}</b><br>${escape(r.horizon)}</p>`:''}${r.terms?`<p><b>Ce que la source apporte :</b> ${escape(r.anchor)}</p><p><b>Nos hypothèses :</b> ${escape(r.notes)}</p>`:`<p>${escape(r.notes)}</p>`}${modelTable(r)}${r.overlap?`<p><b>Doublons / périmètre :</b> ${escape(r.overlap)}</p>`:''}<p><b>${escape(r.counting_note)}</b></p><p class="source-date">${r.terms?'Modèle établi le '+escape(r.model_date||r.date)+' · calcul contrôlé le '+escape(r.calculation_checked||data.updated)+' · dates des repères conservées':'Date du bilan / de l’annonce : '+escape(r.date)}</p>${s?`<a target="_blank" rel="noopener noreferrer" href="${escape(s.url)}">${escape(s.label)} <svg class="arrow-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true" focusable="false"><path d="M5 19 19 5M5 5h14v14"/></svg></a>`:'<p class="source-date">Aucun volume ni coût unitaire événementiel sourcé pour cette ligne : hypothèses éditoriales seulement.</p>'}</div></details>`}).join('')}
function update(mode,animate=true){selected=mode;const target=data.totals[mode]/1e6;document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',String(b.dataset.mode===mode))});document.querySelector('#scenario-status').textContent=data.scenario_labels[mode].toUpperCase()+' · HYPOTHÈSES CONVENTIONNELLES';document.querySelector('#percent').textContent=new Intl.NumberFormat('fr-FR',{maximumFractionDigits:3}).format(data.totals[mode]/data.demand*100)+' %';document.querySelector('#bar').style.width=(data.totals[mode]/data.demand*100)+'%';for(const cat of ['degats','operations','aides'])document.querySelector('#cat-'+cat).textContent=money(data.categories[cat][mode]);document.querySelector('#evidence-split').textContent=money(data.documented_totals[mode])+' de bilans/annonces + '+money(data.modeled_totals[mode])+' d’hypothèses.';render(activeFilter);cancelAnimationFrame(frame);const start=performance.now(),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;function tick(now){const t=animate&&!reduced?Math.min((now-start)/800,1):1;document.querySelector('#amount').textContent=fmt.format(target*(1-Math.pow(1-t,3)));if(t<1)frame=requestAnimationFrame(tick)}frame=requestAnimationFrame(tick)}
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>update(b.dataset.mode)));document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>render(b.dataset.filter)));
document.querySelector('#source-list').innerHTML=Object.entries(data.sources).sort(([a],[b])=>(a==='demande'?-1:b==='demande'?1:0)).map(([id,s],i)=>`<a target="_blank" rel="noopener noreferrer" href="${escape(s.url)}"><span>${String(i+1).padStart(2,'0')}</span><div><b>${escape(s.label)}</b><small>${s.note?escape(s.note):id==='demande'?'Revendication de 10 Md€ · échéancier à préciser':s.kind==='human'?'Source du bilan humain ou de la situation judiciaire ; état daté, non exhaustif':id==='ifrap'?'Ancien modèle archivé, exclu du compteur':'Source du repère décrit dans la fiche ; ne valide pas les hypothèses ni les résultats du modèle.'}</small></div><svg class="arrow-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true" focusable="false"><path d="M5 19 19 5M5 5h14v14"/></svg></a>`).join('');
document.querySelector('#calculation-summary').innerHTML='<div class="table-scroll"><table class="model-table"><thead><tr><th>Composition (€)</th><th>Bas</th><th>Central</th><th>Haut</th></tr></thead><tbody>'+[['Bilans et enveloppe annoncée',data.documented_totals],['Modèles supplémentaires',data.modeled_totals],['Total du scénario',data.totals]].map(([n,v])=>'<tr><th>'+n+'</th>'+['low','central','high'].map(k=>'<td>'+exact.format(v[k])+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
update('central');document.querySelector('#download').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='le-prix-du-refus-'+data.updated+'-v'+data.version+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});

function renderHuman(filter='all'){const cases=data.human.cases.filter(c=>filter==='all'||c.category===filter);document.querySelectorAll('[data-human-filter]').forEach(b=>{const active=b.dataset.humanFilter===filter;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});document.querySelector('#human-count').textContent=cases.length+' fiches affichées · registre non exhaustif';document.querySelector('#human-cases').innerHTML=cases.map(c=>{const s=data.sources[c.source];return `<article class="human-card"><div class="human-meta"><span>${escape(c.city)}</span><span>${c.category==='blessures'?'BLESSURE':c.category==='condamnations'?'PEINE PRONONCÉE':'PROCÉDURE'}</span></div><h3>${escape(c.title)}</h3><p>${escape(c.facts)}</p><div class="human-status"><b>État rapporté</b><p>${escape(c.status)}</p></div><small>${escape(c.date_label)}</small><a target="_blank" rel="noopener noreferrer" href="${escape(s.url)}">${escape(s.label)} <svg class="arrow-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true" focusable="false"><path d="M5 19 19 5M5 5h14v14"/></svg></a></article>`}).join('')};document.querySelectorAll('[data-human-filter]').forEach(b=>b.addEventListener('click',()=>renderHuman(b.dataset.humanFilter)));renderHuman();

// Les compteurs d’accueil utilisent les mêmes données que les détails.
document.querySelector('#front-amount').textContent=fmt.format(data.totals.central/1e6);
const headline=data.human.headline;document.querySelector('.front-human strong').innerHTML=exact.format(headline.value);document.querySelector('.front-demand strong').innerHTML=fmt.format(data.demand/1e9)+' <em>Md€</em>';

const sentencingCases=data.human.cases.filter(c=>c.sentence?.included);
const st=sentencingCases.reduce((t,c)=>({firm:t.firm+c.sentence.firm_months,suspended:t.suspended+c.sentence.suspended_months,people:t.people+c.sentence.people}),{firm:0,suspended:0,people:0});
document.querySelector('#sentence-total').textContent=exact.format(st.firm+st.suspended);
document.querySelector('#sentence-caption').textContent=st.firm+' mois ferme + '+st.suspended+' mois avec sursis · '+st.people+' personnes. Une décision en appel. Pas un total national ni du temps effectivement détenu.';
document.querySelector('#injury-total').textContent=exact.format(data.human.headline.components.reduce((n,c)=>n+c.value,0));
document.querySelector('#sentence-table').innerHTML='<table class="model-table"><thead><tr><th>Dossier / source</th><th>Personnes</th><th>Ferme (mois)</th><th>Sursis (mois)</th><th>Appel</th></tr></thead><tbody>'+sentencingCases.map(c=>'<tr><td><a href="'+escape(data.sources[c.source].url)+'" target="_blank" rel="noopener noreferrer">'+escape(c.city+' · '+c.title)+'</a></td><td>'+c.sentence.people+'</td><td>'+c.sentence.firm_months+'</td><td>'+c.sentence.suspended_months+'</td><td>'+escape(c.sentence.appeal)+'</td></tr>').join('')+'<tr><th>Cumul documenté</th><td>'+st.people+'</td><td>'+st.firm+'</td><td>'+st.suspended+'</td><td>Partiel</td></tr></tbody></table>';
document.querySelector('#other-balances').innerHTML='<h3>Derniers bilans retrouvés · périodes distinctes</h3>'+data.human.balances.map(b=>'<article><h4>'+escape(b.area)+'</h4><p>'+escape(b.text)+'</p><a href="'+escape(data.sources[b.source].url)+'" target="_blank" rel="noopener noreferrer">'+escape(data.sources[b.source].label)+' <svg class="arrow-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true" focusable="false"><path d="M5 19 19 5M5 5h14v14"/></svg></a></article>').join('');


const checkedDate=data.last_checked||data.updated;
const checkedLabel=new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Paris'}).format(new Date(checkedDate+'T12:00:00Z'));
document.querySelectorAll('[data-checked-date]').forEach(el=>{el.textContent=checkedLabel;el.setAttribute('datetime',checkedDate)});
const checkedTitle=document.querySelector('#verification-date');if(checkedTitle)checkedTitle.textContent='ENQUÊTE VÉRIFIÉE LE '+checkedLabel.toUpperCase();
document.querySelector('#human-check-note').textContent='Recherche vérifiée le '+checkedLabel+'. Aucun total national actuel de personnes blessées, sans doublons, n’a pu être établi. Les bilans ci-dessous conservent leurs dates et périmètres.';
document.querySelector('.front-human p').textContent='Repère national du 14 octobre. Recherche vérifiée le '+checkedLabel+' : les bilans plus récents sont détaillés ci-dessous, avec leurs périmètres respectifs.';

const countedRows=data.rows.filter(r=>r.included);document.querySelector('.coverage b').textContent=countedRows.length;document.querySelector('[data-filter="included"]').textContent='Toutes les dépenses · '+countedRows.length;document.querySelector('.range b').textContent=['low','central','high'].map(k=>fmt.format(data.totals[k]/1e6)).join(' / ')+' M€';
